buildGradleAdditions.insert:
dependencies {
    implementation files('libs/sprboxlib-std-0.3.0-release.aar')
    implementation files('libs/sprboxlib-imuadv-0.3.5-release.aar')
    // sprboxlib-std 0.3.0 uses protobuf (protocol v3); flat aar has no POM, so declare it here
    implementation 'com.google.protobuf:protobuf-javalite:4.29.3'
    implementation 'org.jetbrains.kotlin:kotlin-stdlib:1.9.24'
    implementation 'org.jetbrains.kotlinx:kotlinx-coroutines-android:1.9.0'
    implementation 'androidx.core:core-ktx:1.13.1'
    implementation 'androidx.appcompat:appcompat:1.7.0'
}

gameActivityImportAdditions.insert:
import jp.co.sony.sprbox.imuadv.ImuAdvController;
import jp.co.sony.sprbox.imuadv.ImuAdvEstimateData;
import jp.co.sony.sprbox.imuadv.ImuAdvCalibrationResult;
import jp.co.sony.sprbox.std.ServiceConnector;
import jp.co.sony.sprbox.service.IUsbDeviceExt;

gameActivityClassAdditions.insert:
// ===== SprBoxBridge (IMU-Adv) =====
private ImuAdvController sprboxImuController = null;
private final Object sprboxLock = new Object();
private final double[] sprboxImu = new double[10]; // ax,ay,az,gx,gy,gz,rollDeg,pitchDeg,yawDeg,seq
private volatile boolean sprboxSpresenseConnected = false;
private volatile boolean sprboxServiceConnected = false;
private long sprboxSeq = 0;

private final ServiceConnector.ConnectorListener sprboxConnectorListener = new ServiceConnector.ConnectorListener() {
	@Override public void onServiceConnected() { sprboxServiceConnected = true; }
	@Override public void onServiceDisconnected() { sprboxServiceConnected = false; sprboxSpresenseConnected = false; }
	@Override public void onUsbConnected(IUsbDeviceExt device) {}
	@Override public void onUsbDisconnected(IUsbDeviceExt device) {}
};

private final ImuAdvController.Listener sprboxImuListener = new ImuAdvController.Listener() {
	@Override
	public void onImuAdvEvent(ImuAdvEstimateData e) {
		synchronized (sprboxLock) {
			sprboxImu[0] = e.getRaw().getAx();
			sprboxImu[1] = e.getRaw().getAy();
			sprboxImu[2] = e.getRaw().getAz();
			sprboxImu[3] = e.getRaw().getGx();
			sprboxImu[4] = e.getRaw().getGy();
			sprboxImu[5] = e.getRaw().getGz();
			sprboxImu[6] = Math.toDegrees(e.getAttitude().getRoll());
			sprboxImu[7] = Math.toDegrees(e.getAttitude().getPitch());
			sprboxImu[8] = Math.toDegrees(e.getAttitude().getYaw());
			sprboxImu[9] = (double)(++sprboxSeq);
		}
	}
	@Override
	public void onSpresenseConnected() {
		sprboxSpresenseConnected = true;
		if (sprboxImuController != null) {
			try {
				sprboxImuController.start();
			} catch (Throwable t) {
				// libinertialmotionlib2.so is a 4 KB-aligned prebuilt and cannot load on
				// 16 KB page-size devices. Without SPR-BOX samples the game falls back to
				// the phone's own IMU instead of crashing on this callback thread.
				android.util.Log.e("SprBoxBridge", "IMU-Adv start failed; using device IMU", t);
			}
		}
	}
	@Override
	public void onSpresenseDisconnected() {
		sprboxSpresenseConnected = false;
	}
};

public boolean AndroidThunkJava_SprBoxInit(final int rate, final int accelRange, final int gyroRange, final double beta) {
	try {
		if (sprboxImuController == null) {
			sprboxImuController = new ImuAdvController();
			ServiceConnector.INSTANCE.addConnectorListener(sprboxConnectorListener);
		}
		sprboxImuController.setParam(rate, accelRange, gyroRange);
		sprboxImuController.addListener(sprboxImuListener);
		boolean ok = sprboxImuController.open(this);
		if (ok && sprboxImuController.isSpresenseConnected()) {
			sprboxSpresenseConnected = true;
			sprboxImuController.start();
		}
		return ok;
	} catch (Throwable t) {
		android.util.Log.e("SprBoxBridge", "Init failed", t);
		return false;
	}
}

public void AndroidThunkJava_SprBoxShutdown() {
	try {
		if (sprboxImuController != null) {
			sprboxImuController.stop();
			sprboxImuController.close();
			sprboxImuController = null;
		}
		sprboxSpresenseConnected = false;
	} catch (Throwable t) {
		android.util.Log.e("SprBoxBridge", "Shutdown failed", t);
	}
}

public double[] AndroidThunkJava_SprBoxGetImu() {
	synchronized (sprboxLock) {
		return sprboxImu.clone();
	}
}

public boolean AndroidThunkJava_SprBoxIsConnected() {
	return sprboxSpresenseConnected;
}

/** Start one calibration step (SDK collects samples until finish is called). */
public boolean AndroidThunkJava_SprBoxCalibStart(final boolean reuseRunningStream) {
	try {
		if (sprboxImuController != null && sprboxSpresenseConnected) {
			return sprboxImuController.startCalibration(ImuAdvController.DEFAULT_CALIBRATION_KIND, reuseRunningStream);
		}
	} catch (Throwable t) {
		android.util.Log.e("SprBoxBridge", "CalibStart failed", t);
	}
	return false;
}

/** Finish the current calibration step. Returns true on success. */
public boolean AndroidThunkJava_SprBoxCalibFinish() {
	try {
		if (sprboxImuController != null) {
			ImuAdvCalibrationResult r = sprboxImuController.finishCalibration(false, true);
			return r != null;
		}
	} catch (Throwable t) {
		android.util.Log.e("SprBoxBridge", "CalibFinish failed", t);
	}
	return false;
}

/** Quick attitude reset (drift fix) - SDK lightReset. */
public boolean AndroidThunkJava_SprBoxLightReset() {
	try {
		if (sprboxImuController != null) {
			return sprboxImuController.lightReset();
		}
	} catch (Throwable t) {
		android.util.Log.e("SprBoxBridge", "LightReset failed", t);
	}
	return false;
}

/** Kept for compatibility: maps to lightReset in IMU-Adv mode. */
public void AndroidThunkJava_SprBoxRecalibrate() {
	AndroidThunkJava_SprBoxLightReset();
}

/** bit0 = SPR-BOX Service bound, bit1 = Spresense board connected */
public int AndroidThunkJava_SprBoxGetStatus() {
	int status = 0;
	if (sprboxServiceConnected) status |= 1;
	if (sprboxSpresenseConnected) status |= 2;
	return status;
}
